#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <arpa/inet.h>

#define MAX_RECORD_SIZE 16384
#define MAX_EXTENSIONS 32
#define TLS_HANDSHAKE 22
#define TLS_CLIENT_HELLO 1

typedef struct {
    uint8_t content_type;
    uint16_t version;
    uint16_t length;
    uint8_t *fragment;
} tls_record_t;

typedef struct {
    uint16_t type;
    uint16_t length;
    uint8_t *data;
} extension_t;

typedef struct {
    uint8_t handshake_type;
    uint16_t client_version;
    uint8_t random[32];
    uint8_t session_id_len;
    uint8_t *session_id;
    uint16_t cipher_suites_len;
    uint16_t *cipher_suites;
    uint8_t compression_len;
    uint8_t *compression_methods;
    uint16_t extensions_len;
    extension_t extensions[MAX_EXTENSIONS];
    int num_extensions;
} client_hello_t;

/* Parse TLS record layer */
int parse_tls_record(const uint8_t *buf, size_t buf_len, tls_record_t *record) {
    if (buf_len < 5) return -1;

    record->content_type = buf[0];
    record->version = (buf[1] << 8) | buf[2];
    record->length = (buf[3] << 8) | buf[4];

    if (record->length > MAX_RECORD_SIZE) return -1;
    if (buf_len < (size_t)(5 + record->length)) return -1;

    record->fragment = (uint8_t *)buf + 5;
    return 0;
}

/* Validate extension data doesn't contain null bytes (for SNI logging) */
int validate_extension_content(const uint8_t *data, uint16_t len) {
    /* Bounds check: ensure length is reasonable */
    if (len > MAX_RECORD_SIZE) return -1;

    for (uint16_t i = 0; i < len; i++) {
        if (data[i] == 0x00 && i > 0) {
            /* Null byte in middle of extension - suspicious */
            return -1;
        }
    }
    return 0;
}

/* Parse extensions from ClientHello */
int parse_extensions(const uint8_t *data, size_t data_len, 
                     uint16_t ext_block_len, client_hello_t *hello) {
    uint16_t offset = 0;
    hello->num_extensions = 0;

    /* Validate extension block fits within data */
    if (ext_block_len > (uint16_t)data_len) return -1;

    while (offset < ext_block_len && hello->num_extensions < MAX_EXTENSIONS) {
        if (ext_block_len - offset < 4) return -1;

        uint16_t ext_type = (data[offset] << 8) | data[offset + 1];
        uint16_t ext_len = (uint16_t)((data[offset + 2] << 8) | data[offset + 3]);
        offset += 4;

        /* Safety check: extension length must not exceed remaining block */
        if (ext_len > ext_block_len - offset) return -1;

        hello->extensions[hello->num_extensions].type = ext_type;
        hello->extensions[hello->num_extensions].length = ext_len;
        hello->extensions[hello->num_extensions].data = (uint8_t *)data + offset;

        /* Validate content for SNI extensions */
        if (ext_type == 0x0000) {
            if (validate_extension_content(data + offset, ext_len) != 0) {
                return -1;
            }
        }

        hello->num_extensions++;
        offset += ext_len;
    }
    return 0;
}

/* Parse ClientHello message */
int parse_client_hello(const uint8_t *fragment, size_t frag_len, client_hello_t *hello) {
    if (frag_len < 4) return -1;

    /* Handshake header */
    hello->handshake_type = fragment[0];
    if (hello->handshake_type != TLS_CLIENT_HELLO) return -1;

    uint32_t hs_length = (fragment[1] << 16) | (fragment[2] << 8) | fragment[3];
    if (hs_length + 4 > frag_len) return -1;

    size_t pos = 4;

    /* Client version */
    if (pos + 2 > frag_len) return -1;
    hello->client_version = (fragment[pos] << 8) | fragment[pos + 1];
    pos += 2;

    /* Random */
    if (pos + 32 > frag_len) return -1;
    memcpy(hello->random, fragment + pos, 32);
    pos += 32;

    /* Session ID */
    if (pos + 1 > frag_len) return -1;
    hello->session_id_len = fragment[pos];
    pos += 1;
    if (pos + hello->session_id_len > frag_len) return -1;
    hello->session_id = (uint8_t *)fragment + pos;
    pos += hello->session_id_len;

    /* Cipher suites */
    if (pos + 2 > frag_len) return -1;
    hello->cipher_suites_len = (fragment[pos] << 8) | fragment[pos + 1];
    pos += 2;
    if (pos + hello->cipher_suites_len > frag_len) return -1;
    hello->cipher_suites = (uint16_t *)(fragment + pos);
    pos += hello->cipher_suites_len;

    /* Compression methods */
    if (pos + 1 > frag_len) return -1;
    hello->compression_len = fragment[pos];
    pos += 1;
    if (pos + hello->compression_len > frag_len) return -1;
    hello->compression_methods = (uint8_t *)fragment + pos;
    pos += hello->compression_len;

    /* Extensions */
    if (pos + 2 > frag_len) return -1;
    hello->extensions_len = (fragment[pos] << 8) | fragment[pos + 1];
    pos += 2;

    if (pos + hello->extensions_len > frag_len) return -1;

    uint16_t ext_block_len = hello->extensions_len;
    return parse_extensions(fragment + pos, frag_len - pos, ext_block_len, hello);
}

/* Extract SNI hostname for logging */
char *extract_sni(client_hello_t *hello) {
    for (int i = 0; i < hello->num_extensions; i++) {
        if (hello->extensions[i].type == 0x0000 && hello->extensions[i].length >= 5) {
            uint8_t *sni_data = hello->extensions[i].data;
            uint16_t list_len = (sni_data[0] << 8) | sni_data[1];
            uint8_t name_type = sni_data[2];
            uint16_t name_len = (sni_data[3] << 8) | sni_data[4];

            if (name_type == 0 && name_len <= hello->extensions[i].length - 5) {
                char *hostname = malloc(name_len + 1);
                if (!hostname) return NULL;
                memcpy(hostname, sni_data + 5, name_len);
                hostname[name_len] = '\0';
                return hostname;
            }
        }
    }
    return NULL;
}

/* Process incoming TLS connection */
void process_connection(const uint8_t *data, size_t data_len) {
    tls_record_t record;
    client_hello_t hello;

    memset(&hello, 0, sizeof(hello));

    if (parse_tls_record(data, data_len, &record) != 0) {
        fprintf(stderr, "Invalid TLS record\n");
        return;
    }

    if (record.content_type != TLS_HANDSHAKE) {
        fprintf(stderr, "Not a handshake record\n");
        return;
    }

    if (parse_client_hello(record.fragment, record.length, &hello) != 0) {
        fprintf(stderr, "Invalid ClientHello\n");
        return;
    }

    char *sni = extract_sni(&hello);
    if (sni) {
        printf("SNI: %s\n", sni);
        free(sni);
    }
}

int main(int argc, char *argv[]) {
    /* Read TLS ClientHello from stdin for testing */
    uint8_t buf[65536];
    size_t n = fread(buf, 1, sizeof(buf), stdin);
    if (n > 0) {
        process_connection(buf, n);
    }
    return 0;
}
